import{_ as n,c as i,o as t,ah as r}from"./chunks/framework.dGCgOE9J.js";const d="/Qonnectra-docs/pr-27/images/manual/teil-b/ops_logs.jpg",s="/Qonnectra-docs/pr-27/images/manual/teil-b/ops_logs_admin.jpg",b=JSON.parse('{"title":"28. Betrieb der Instanz","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.md","filePath":"manual/teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.md"}'),a={name:"manual/teil-b-betrieb-admin-qgis/28-betrieb-der-instanz.md"};function l(o,e,c,h,u,g){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="_28-betrieb-der-instanz" tabindex="-1">28. Betrieb der Instanz <a class="header-anchor" href="#_28-betrieb-der-instanz" aria-label="Permalink to &quot;28. Betrieb der Instanz&quot;">​</a></h1><p>Dieses Kapitel richtet sich an die Stelle, die den Server betreibt, auf dem Qonnectra läuft. Es beschreibt, aus welchen Diensten eine Installation besteht, welche Einstellungen im laufenden Betrieb angefasst werden, und wie Aktualisierung, Sicherung, Protokolle und die Hintergrundkarte gehandhabt werden. Die Installation selbst und die vollständige Liste der Einstellungen beschreibt Teil C, siehe Kapitel <a href="./../teil-c-entwicklungs-systemdokumentation/35-bereitstellung-und-infrastruktur.html">Bereitstellung und Infrastruktur</a>.</p><p>Alle Befehle dieses Kapitels werden auf dem Server im Ordner <code>deployment</code> der Installation ausgeführt.</p><h2 id="_28-1-systemuberblick-dienste-und-ihre-aufgaben" tabindex="-1">28.1 Systemüberblick: Dienste und ihre Aufgaben <a class="header-anchor" href="#_28-1-systemuberblick-dienste-und-ihre-aufgaben" aria-label="Permalink to &quot;28.1 Systemüberblick: Dienste und ihre Aufgaben&quot;">​</a></h2><p>Qonnectra läuft als Gruppe von Docker-Containern, beschrieben in <code>docker-compose.yml</code>:</p><table tabindex="0"><thead><tr><th>Dienst</th><th>Aufgabe</th></tr></thead><tbody><tr><td><code>caddy</code></td><td>nimmt alle Anfragen aus dem Internet an, verteilt sie nach Adresse auf die übrigen Dienste und holt die HTTPS-Zertifikate; liefert außerdem den WebDAV-Zugang aus</td></tr><tr><td><code>frontend</code></td><td>die Weboberfläche</td></tr><tr><td><code>nginx</code></td><td>leitet Anfragen an das Backend weiter, liefert Anhänge aus und hält Kartenkacheln und WMS-Bilder zwischengespeichert</td></tr><tr><td><code>backend</code></td><td>die Schnittstelle und der Administrationsbereich</td></tr><tr><td><code>backend-wms</code></td><td>ein zweites Backend nur für den WMS-Proxy, damit langsame Kartendienste die übrige Anwendung nicht ausbremsen</td></tr><tr><td><code>db</code></td><td>die Datenbank, PostgreSQL mit PostGIS</td></tr><tr><td><code>qgis-server</code></td><td>die Kartendienste, siehe Kapitel <a href="./27-qgis-server-und-kartendienste.html">QGIS-Server und Kartendienste</a></td></tr><tr><td><code>tileserver</code></td><td>die Hintergrundkarte, siehe Abschnitt <a href="#_28-6-kartenkacheln-bereitstellen-und-erneuern">Kartenkacheln bereitstellen und erneuern</a></td></tr><tr><td><code>pg-error-parser</code></td><td>liest die Fehler der Datenbank mit und schreibt sie in die Protokolle, siehe Abschnitt <a href="#_28-5-protokolle-auswerten">Protokolle auswerten</a></td></tr><tr><td><code>wireguard</code></td><td>das VPN für den direkten Datenbankzugang aus QGIS; startet immer und öffnet nach außen den UDP-Port 51820 (<code>WIREGUARD_PORT</code>), auch wenn kein QGIS-Arbeitsplatz ihn nutzt</td></tr></tbody></table><p>Nach außen hat eine Installation sechs Adressen, je eine für die Weboberfläche (<code>app.</code>), die Schnittstelle (<code>api.</code>), den Administrationsbereich (<code>admin.</code>), den WebDAV-Zugang (<code>files.</code>), den QGIS-Server (<code>qgis.</code>) und die Hintergrundkarte (<code>tiles.</code>).</p><p>Die Daten liegen in Docker-Volumes: die Datenbank in <code>qonnectra_postgres_data_prod</code>, die Anhänge in <code>qonnectra_media_prod</code>, die Zertifikate in <code>qonnectra_caddy_data_prod</code>, der Zwischenspeicher der WMS-Bilder in <code>qonnectra_wms_cache_prod</code>. In <code>docker-compose.yml</code> stehen sie unter kürzeren Namen (<code>postgres_data</code>, <code>media_volume</code> usw.); <code>docker volume ls</code> zeigt die vollständigen. Die hinterlegten QGIS-Projekte und ihre Datendateien liegen im Ordner <code>deployment/qgis</code>.</p><h2 id="_28-2-konfiguration-uber-umgebungsvariablen" tabindex="-1">28.2 Konfiguration über Umgebungsvariablen <a class="header-anchor" href="#_28-2-konfiguration-uber-umgebungsvariablen" aria-label="Permalink to &quot;28.2 Konfiguration über Umgebungsvariablen&quot;">​</a></h2><p>Die Einstellungen stehen in der Datei <code>deployment/.env</code>. Die vollständige Liste beschreibt Kapitel <a href="./../teil-c-entwicklungs-systemdokumentation/35-bereitstellung-und-infrastruktur.html">Bereitstellung und Infrastruktur</a>; im laufenden Betrieb werden vor allem diese angefasst:</p><ul><li><strong>Adressen</strong> – <code>APP_DOMAIN</code>, <code>API_DOMAIN</code>, <code>ADMIN_DOMAIN</code>, <code>FILES_DOMAIN</code>, <code>QGIS_DOMAIN</code>, <code>TILE_SERVER_DOMAIN</code>. Jede Adresse muss außerdem in <code>DJANGO_ALLOWED_HOSTS</code> stehen, die Adressen von Weboberfläche und Administrationsbereich zusätzlich in <code>CSRF_TRUSTED_ORIGINS</code>.</li><li><strong><code>COOKIE_DOMAIN</code></strong> – die gemeinsame Domain aller Adressen mit führendem Punkt, etwa <code>.ihre-domain.de</code>. Die Anmeldung gilt über sie für alle Adressen.</li><li><strong><code>PUBLIC_DOCUMENTATION_URL</code></strong> – der Link „Dokumentation“ in Kopfzeile und Navigationsleiste; leer blendet ihn aus.</li><li><strong><code>QGIS_SERVER_VERSION</code></strong> – die Version des QGIS-Servers, für die Warnung beim Hochladen von QGIS-Projekten.</li><li><strong><code>WIREGUARD_PEERS</code></strong> – die Namen der VPN-Zugänge, siehe Abschnitt <a href="./25-qgis-arbeitsplatz-einrichten.html#_25-2-verbindung-zur-postgis-datenbank-und-zu-den-diensten">Verbindung zur PostGIS-Datenbank</a>.</li></ul><p>Das erste Superuser-Konto legt das Backend aus <code>DJANGO_SUPERUSER_USERNAME</code>, <code>DJANGO_SUPERUSER_PASSWORD</code> und <code>DJANGO_SUPERUSER_EMAIL</code> an. Es prüft das bei jedem Start und legt das Konto nur an, wenn es noch keines mit diesem Benutzernamen gibt. Setzen Sie die drei Werte vor dem ersten Start; die Vorlage enthält für das Passwort nur einen Platzhalter.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ein später in <code>.env</code> geändertes Passwort ändert das bestehende Konto nicht; setzen Sie es im Benutzerformular des Administrationsbereichs neu, siehe Abschnitt <a href="./19-rollen-und-rechte.html#_19-1-benutzende-und-gruppen-anlegen">Benutzende und Gruppen anlegen</a>. Ein geänderter Benutzername legt beim nächsten Start ein weiteres Superuser-Konto an.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p><code>FIELD_ENCRYPTION_KEY</code> verschlüsselt die Passwörter der WMS-Quellen. Geht der Schlüssel verloren oder wird er geändert, lassen sich diese Passwörter nicht mehr lesen, und jede WMS-Quelle mit Anmeldung muss neu eingegeben werden. Sichern Sie die Datei <code>.env</code> mit, siehe Abschnitt <a href="#_28-4-sicherung-und-wiederherstellung">Sicherung und Wiederherstellung</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ändern Sie <code>DB_PASSWORD</code> und <code>QGIS_DB_PASSWORD</code> nicht in der Datei allein. Die Datenbank übernimmt sie nur beim ersten Start; danach passt die Datei nicht mehr zur Datenbank, und Backend und QGIS-Server erreichen sie nicht.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p><code>DEFAULT_SRID</code> legt das Koordinatenbezugssystem der Geometrien fest. Ändern Sie es nie, sobald Daten erfasst sind – die vorhandenen Koordinaten würden danach falsch gelesen.</p></div><p>Eine geänderte Variable wirkt erst, wenn die betroffenen Dienste neu erstellt werden:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Die Adresse der Schnittstelle (<code>API_URL</code>, <code>PUBLIC_API_URL</code>) ist in die Weboberfläche eingebaut. Wer sie ändert, muss die Weboberfläche neu bauen:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="_28-3-aktualisierung-auf-eine-neue-version" tabindex="-1">28.3 Aktualisierung auf eine neue Version <a class="header-anchor" href="#_28-3-aktualisierung-auf-eine-neue-version" aria-label="Permalink to &quot;28.3 Aktualisierung auf eine neue Version&quot;">​</a></h2><p>Qonnectra wird aus dem Quellcode gebaut. Eine Aktualisierung:</p><ol><li><p>Sichern Sie Datenbank, Anhänge und <code>.env</code>, siehe Abschnitt <a href="#_28-4-sicherung-und-wiederherstellung">Sicherung und Wiederherstellung</a>.</p></li><li><p>Lesen Sie im <code>CHANGELOG.md</code> der neuen Version, ob sie neue Umgebungsvariablen verlangt, und vergleichen Sie <code>deployment/.env</code> mit <code>.env.production.template</code>.</p></li><li><p>Holen Sie die neue Version, etwa mit <code>git fetch --tags</code> und <code>git checkout v1.8.0</code>.</p></li><li><p>Bauen und starten Sie die Dienste neu:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Prüfen Sie mit <code>docker compose ps</code>, dass alle Dienste laufen, und melden Sie sich in der Weboberfläche und im Administrationsbereich an.</p></li></ol><p>Beim Start bringt das Backend die Datenbank selbst auf den neuen Stand. Bis dahin antworten Weboberfläche und Schnittstelle mit Fehlern; das dauert je nach Umfang der Änderungen einige Minuten.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Neue Stammdaten, die eine Version mitbringt, kommen nur in eine leere Installation. Das Backend lädt seine Grundausstattung gruppenweise und überspringt jede Gruppe, von der es schon Einträge gibt. Bringt eine Version etwa einen neuen Netzknotentyp mit, legen Sie ihn in einer bestehenden Installation selbst an, siehe Kapitel <a href="./21-projekte-und-stammdaten.html">Projekte und Stammdaten pflegen</a>.</p></div><p>Die Versionsnummer in der Kopfzeile der Weboberfläche zeigt nach der Aktualisierung die neue Version, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/01-erste-schritte.html#_1-4-sprache-hell-und-dunkelmodus-versionsanzeige-und-dokumentation">Sprache, Hell- und Dunkelmodus, Versionsanzeige und Dokumentation</a>.</p><h2 id="_28-4-sicherung-und-wiederherstellung" tabindex="-1">28.4 Sicherung und Wiederherstellung <a class="header-anchor" href="#_28-4-sicherung-und-wiederherstellung" aria-label="Permalink to &quot;28.4 Sicherung und Wiederherstellung&quot;">​</a></h2><p>Eine vollständige Sicherung umfasst:</p><ul><li>die Datenbank,</li><li>die Anhänge im Volume <code>qonnectra_media_prod</code>,</li><li>die QGIS-Projekte und ihre Datendateien in <code>deployment/qgis</code>,</li><li>die Datei <code>deployment/.env</code>,</li><li>die Zertifikate im Volume <code>qonnectra_caddy_data_prod</code> und die VPN-Zugänge in <code>deployment/wireguard</code>, falls verwendet.</li></ul><p>Die Datenbank allein sichern Sie mit:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DB_USE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">R</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DB_NAM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">E</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=custom</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qonnectra.dump</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Datenbank und Anhänge gehören zusammen: Jeder Anhang hat einen Eintrag in der Datenbank, siehe Kapitel <a href="./23-dateien-und-anhaenge.html">Dateien und Anhänge verwalten</a>. Sichern Sie beide zur selben Zeit; eine ältere Datenbank mit neueren Anhängen ergibt Dateien ohne Eintrag, eine neuere Datenbank mit älteren Anhängen Einträge ohne Datei.</p><p>Im Ordner <code>deployment/backup</code> liegen zwei Skripte, <code>backup.sh</code> und <code>restore.sh</code>, die das alles erledigen und die Sicherungen zusätzlich mit <code>rclone</code> an einen entfernten Speicher übertragen. Sie lesen ihre Einstellungen – Zielordner, Namen der Container und Volumes, Ziel von <code>rclone</code>, Aufbewahrungsdauer – aus einer Datei <code>backup.conf</code> daneben, die Sie selbst anlegen; sie wird nicht mitgeliefert. Richten Sie <code>backup.sh</code> als nächtliche Aufgabe ein. <code>restore.sh</code> mit einem Datum stellt die Sicherung dieses Tages wieder her, mit <code>--db-only</code> oder <code>--media-only</code> nur einen Teil, mit <code>--list</code> zeigt es die vorhandenen Sicherungen.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Tragen Sie in <code>backup.conf</code> unter <code>MEDIA_VOLUME</code> und <code>CADDY_VOLUME</code> die vollständigen Namen der Volumes ein, <code>qonnectra_media_prod</code> und <code>qonnectra_caddy_data_prod</code>, nicht die kurzen aus <code>docker-compose.yml</code>. Ein Volume mit falschem Namen legt Docker beim Sichern ohne Meldung neu und leer an – die Sicherung läuft durch und enthält keine Anhänge.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Eine Wiederherstellung ersetzt die Datenbank vollständig. Alles, was seit der Sicherung erfasst wurde, ist danach verloren. Stellen Sie im Zweifel zuerst in eine zweite Installation wieder her und übernehmen Sie nur, was fehlt.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Auch mit einem Datum stellt <code>restore.sh</code> nicht die Anhänge dieses Tages her. Die Anhänge liegen in einem einzigen Spiegel am entfernten Speicher, den jede Sicherung nur ergänzt und aus dem nie etwas gelöscht wird. Wiederhergestellt wird immer der Stand der letzten Sicherung, samt aller Dateien, die in Qonnectra inzwischen gelöscht wurden; zu einer älteren Datenbank ergibt das Dateien ohne Eintrag.</p><p>Die Datei <code>.env</code> stellt das Skript nicht wieder her, es nennt nur den Pfad der gesicherten Kopie. Vergleichen und übernehmen Sie sie selbst.</p><p><code>restore.sh</code> liest <code>.env</code> als Shell-Skript ein und bricht sofort ab, wenn eine Zeile dort Leerzeichen um das Gleichheitszeichen hat. Die Vorlage <code>.env.production.template</code> enthält eine solche Zeile (<code>COOKIE_DOMAIN = .your-domain.com</code>). Schreiben Sie jede Zuweisung ohne Leerzeichen, etwa <code>COOKIE_DOMAIN=.ihre-domain.de</code>.</p></div><p>Prüfen Sie Sicherungen regelmäßig durch eine Wiederherstellung auf einem Testsystem.</p><h2 id="_28-5-protokolle-auswerten" tabindex="-1">28.5 Protokolle auswerten <a class="header-anchor" href="#_28-5-protokolle-auswerten" aria-label="Permalink to &quot;28.5 Protokolle auswerten&quot;">​</a></h2><p>Qonnectra schreibt Fehler und Warnungen in eine eigene Protokolltabelle. Jeder Eintrag hat eine Stufe, eine Quelle, das Konto, das Projekt und die Nachricht. Es gibt drei Quellen:</p><ul><li><strong>„Backend“</strong> – Fehler und Warnungen der Schnittstelle, etwa ein abgelehnter Import oder eine Anfrage, die mit einem Serverfehler endete.</li><li><strong>„Frontend“</strong> – Fehler, die im Browser der Nutzenden auftreten und die die Weboberfläche meldet, etwa ein gescheitertes Hochladen eines Anhangs oder eine Suche ohne Antwort.</li><li><strong>„WFS (QGIS Server)“</strong> – jeder Fehler, den die Datenbank meldet, etwa ein abgelehntes Löschen aus QGIS, siehe Kapitel <a href="./26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>. Trotz des Namens stehen hier auch Datenbankfehler, die die Weboberfläche ausgelöst hat. Diese Einträge haben weder Konto noch Projekt.</li></ul><p>Die Einträge sehen Sie an zwei Stellen. In der Weboberfläche unter „Logs“ am Fuß der Navigationsleiste, mit Filtern nach Stufe, Quelle, Projekt, Text und Zeitraum:</p><p><img src="'+d+'" alt="Screenshot der Seite „Logs“ der Weboberfläche mit den Filtern oben und der Liste der Einträge darunter" data-zoomable="true"></p><p>Wer die Seite öffnen darf, beschreibt Abschnitt <a href="./19-rollen-und-rechte.html#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p><p>Im Administrationsbereich unter „Log-Einträge“, mit denselben Filtern und zusätzlich zwei Aktionen zum Löschen: „Ausgewählte Log-Einträge löschen“ für die angehakten Einträge und „Alle Log-Einträge mit aktuellen Filtern löschen“ für alle, die der Filter zeigt.</p><p><img src="'+s+'" alt="Screenshot der Log-Einträge im Administrationsbereich mit Hervorhebung der Filter rechts und der Aktionen über der Liste, Ausschnitt des oberen Teils" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Protokolltabelle wächst ohne Grenze; Qonnectra löscht keine Einträge von selbst. Löschen Sie alte Einträge regelmäßig, etwa alle, die älter als ein Jahr sind. Ohne Filter löscht „Alle Log-Einträge mit aktuellen Filtern löschen“ das gesamte Protokoll.</p></div><p>Meldet jemand einen Fehler, finden Sie den Eintrag über Zeitpunkt und Konto, siehe Abschnitt <a href="./../teil-a-anwenderhandbuch/18-wenn-etwas-nicht-funktioniert.html#_18-5-was-das-support-team-von-ihnen-braucht">Was das Support-Team von Ihnen braucht</a>. Einträge der Quelle „WFS (QGIS Server)“ finden Sie nur über den Zeitpunkt; ein Filter nach Projekt blendet sie aus. Mehr als die Protokolltabelle zeigen die Ausgaben der Container selbst:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Docker behält davon je Dienst nur die letzten 30 MB – außer bei <code>nginx</code> und <code>caddy</code>, deren Ausgaben <code>docker-compose.yml</code> nicht begrenzt. Sie wachsen, solange die Docker-Einstellungen des Servers keine Grenze setzen.</p><h2 id="_28-6-kartenkacheln-bereitstellen-und-erneuern" tabindex="-1">28.6 Kartenkacheln bereitstellen und erneuern <a class="header-anchor" href="#_28-6-kartenkacheln-bereitstellen-und-erneuern" aria-label="Permalink to &quot;28.6 Kartenkacheln bereitstellen und erneuern&quot;">​</a></h2><p>Die Hintergrundkarte der Weboberfläche liefert der Dienst <code>tileserver</code> aus einer Kacheldatei im Format MBTiles, die im Ordner <code>deployment/tiles</code> liegt; ihren Namen nennt <code>deployment/tiles/config.json</code>. Qonnectra bringt keine Kacheldatei mit. Sie wird aus Daten von OpenStreetMap erzeugt, mit dem Werkzeug <a href="https://github.com/onthegomap/planetiler" target="_blank" rel="noreferrer">Planetiler</a>, für das Gebiet, in dem die Netze liegen – ein Bundesland genügt meist.</p><p>So erneuern Sie die Karte:</p><ol><li>Erzeugen Sie eine neue Kacheldatei mit Planetiler aus einem aktuellen Auszug von OpenStreetMap.</li><li>Legen Sie sie in <code>deployment/tiles</code> ab und tragen Sie ihren Namen in <code>config.json</code> ein.</li><li>Starten Sie den Dienst neu: <code>docker compose restart tileserver</code>.</li></ol><p>Die Adresse des Kachelservers steht in <code>PUBLIC_TILE_SERVER_URL</code>. Fehlt sie, zeigt die Karte stattdessen die Kacheln von OpenStreetMap aus dem Internet.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Fehlt die Kacheldatei, startet der Dienst <code>tileserver</code> immer wieder neu; <code>docker compose ps</code> zeigt ihn dann als „Restarting“. Die Karte zeigt in dieser Zeit die Kacheln von OpenStreetMap aus dem Internet und bleibt nur leer, wenn auch diese nicht erreichbar sind. Der Ausfall fällt in der Weboberfläche deshalb kaum auf.</p></div><h2 id="_28-7-haufige-storungen-und-ihre-behebung" tabindex="-1">28.7 Häufige Störungen und ihre Behebung <a class="header-anchor" href="#_28-7-haufige-storungen-und-ihre-behebung" aria-label="Permalink to &quot;28.7 Häufige Störungen und ihre Behebung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anzeichen</th><th>Ursache</th><th>Behebung</th></tr></thead><tbody><tr><td>Nach einem Neustart des Backends antwortet die Schnittstelle dauerhaft mit „502“</td><td><code>nginx</code> hält die alte interne Adresse des Backends fest</td><td><code>docker compose restart nginx</code></td></tr><tr><td>Anmeldung in der Weboberfläche führt sofort zurück zur Anmeldeseite</td><td><code>COOKIE_DOMAIN</code> passt nicht zu den Adressen</td><td><code>COOKIE_DOMAIN</code> auf die gemeinsame Domain mit führendem Punkt setzen</td></tr><tr><td>Anmeldung im Administrationsbereich endet mit „403“</td><td>Adresse des Administrationsbereichs fehlt in <code>CSRF_TRUSTED_ORIGINS</code></td><td>ergänzen, <code>docker compose up -d</code></td></tr><tr><td>WebDAV oder die Dienste des QGIS-Servers antworten auf jede Anmeldung mit „400“</td><td><code>files.</code>- oder <code>qgis.</code>-Adresse fehlt in <code>DJANGO_ALLOWED_HOSTS</code></td><td>ergänzen, <code>docker compose up -d</code></td></tr><tr><td>Hintergrundkarte zeigt die Kacheln von OpenStreetMap statt der eigenen oder bleibt leer, <code>tileserver</code> startet ständig neu</td><td>Kacheldatei fehlt oder <code>config.json</code> nennt einen falschen Namen</td><td>siehe Abschnitt <a href="#_28-6-kartenkacheln-bereitstellen-und-erneuern">Kartenkacheln</a></td></tr><tr><td>WMS-Layer zeigt veraltete Bilder</td><td>Zwischenspeicher des WMS-Proxys</td><td><code>docker compose exec nginx sh -c &#39;rm -rf /var/cache/nginx/wms/*&#39;</code></td></tr><tr><td>WMS-Quellen mit Anmeldung liefern nichts mehr</td><td><code>FIELD_ENCRYPTION_KEY</code> geändert</td><td>alten Schlüssel wiederherstellen oder Passwörter neu eingeben</td></tr><tr><td>Neue Daten erscheinen in der Karte erst nach einer halben Minute, in bisher leeren Kartenbereichen nach bis zu zehn Minuten, im Dashboard nach Minuten</td><td>Zwischenspeicher, gewollt</td><td>abwarten, siehe Abschnitt <a href="./26-netzdaten-in-qgis-bearbeiten.html#_26-3-gleichzeitiges-arbeiten-mit-der-weboberflache">Gleichzeitiges Arbeiten mit der Weboberfläche</a></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der Administrationsbereich und der WebDAV-Zugang sind aus dem ganzen Internet erreichbar. Wer sie auf das eigene Netz oder das VPN beschränken will, ergänzt in <code>Caddyfile.production</code> bei der jeweiligen Adresse eine Sperre nach Absender-IP; ein Beispiel steht dort beim Administrationsbereich als Kommentar.</p></div>',58)])])}const m=n(a,[["render",l]]);export{b as __pageData,m as default};
